insert into problems(lesson_id,sort,title,input,output,solution,explanation,solution2,explanation2) values
(209,170,E'LRU cache',E'2\n5\nput 1 1\nput 2 2\nget 1\nput 3 3\nget 2',E'1\n-1',E'from collections import OrderedDict\ncap = int(input())\nn = int(input())\nd = OrderedDict()\nfor _ in range(n):\n    op = input().split()\n    if op[0] == ''put'':\n        k, v = int(op[1]), int(op[2])\n        d[k] = v\n        d.move_to_end(k)\n        if len(d) > cap:\n            d.popitem(last=False)\n    else:\n        k = int(op[1])\n        if k in d:\n            d.move_to_end(k)\n            print(d[k])\n        else:\n            print(-1)',E'OrderedDict: వాడిన key చివరికి, capacity దాటితే మొదటిది తొలగింపు.',E'cap = int(input())\nn = int(input())\nd = {}\nfor _ in range(n):\n    op = input().split()\n    k = int(op[1])\n    if op[0] == ''put'':\n        d.pop(k, None)\n        d[k] = int(op[2])\n        if len(d) > cap:\n            del d[next(iter(d))]\n    elif k in d:\n        d[k] = d.pop(k)\n        print(d[k])\n    else:\n        print(-1)',E'సాధారణ dict లో pop + re-insert తో recency; మొదటి key = least recent.'),
(209,171,E'Longest substring with K distinct',E'eceba\n2',E'3',E's = input()\nk = int(input())\ncnt = {}\nl = best = 0\nfor r, c in enumerate(s):\n    cnt[c] = cnt.get(c, 0) + 1\n    while len(cnt) > k:\n        cnt[s[l]] -= 1\n        if cnt[s[l]] == 0:\n            del cnt[s[l]]\n        l += 1\n    best = max(best, r - l + 1)\nprint(best)',E'Sliding window + count dict: distinct > k అయితే ఎడమ కుదించాం. O(n).',E's = input()\nk = int(input())\nprint(max(j - i for i in range(len(s)) for j in range(i + 1, len(s) + 1) if len(set(s[i:j])) <= k))',E'అన్ని substrings, set తో distinct: O(n³).'),
(209,172,E'Duplicate within distance k',E'1 2 3 1\n3',E'True',E'a = input().split()\nk = int(input())\nlast = {}\nans = False\nfor i, x in enumerate(a):\n    if x in last and i - last[x] <= k:\n        ans = True\n        break\n    last[x] = i\nprint(ans)',E'చివరి index dict; దూరం ≤ k చూశాం.',E'a = input().split()\nk = int(input())\nw = set()\nans = False\nfor i, x in enumerate(a):\n    if x in w:\n        ans = True\n        break\n    w.add(x)\n    if len(w) > k:\n        w.remove(a[i - k])\nprint(ans)',E'Size-k window set: పాతది తొలగిస్తూ.'),
(209,173,E'Group by digit sum',E'12 21 13 31 4',E'{3: [12, 21], 4: [13, 31, 4]}',E'from collections import defaultdict\nd = defaultdict(list)\nfor w in input().split():\n    d[sum(map(int, w))].append(int(w))\nprint(dict(sorted(d.items())))',E'Digit sum key గా defaultdict grouping.',E'from itertools import groupby\nds = lambda w: sum(map(int, w))\nws = sorted(input().split(), key=ds)\nprint({k: [int(w) for w in g] for k, g in groupby(ws, key=ds)})',E'Key తో sort (stable) చేసి groupby.'),
(209,174,E'Longest harmonious subsequence',E'1 3 2 2 5 2 3 7',E'5',E'from collections import Counter\nc = Counter(map(int, input().split()))\nprint(max((v + c[k + 1] for k, v in c.items() if k + 1 in c), default=0))',E'x మరియు x+1 counts కలిపాం: O(n).',E'a = list(map(int, input().split()))\nprint(max((a.count(x) + a.count(x + 1) for x in set(a) if x + 1 in a), default=0))',E'count() తో అదే logic: O(n²).'),
(210,175,E'Counter closure',E'3',E'1\n2\n3',E'def make():\n    c = 0\n    def inc():\n        nonlocal c\n        c += 1\n        return c\n    return inc\nf = make()\nfor _ in range(int(input())):\n    print(f())',E'inc() outer variable c ని nonlocal తో మారుస్తుంది; state గుర్తుంటుంది.',E'class Counter:\n    def __init__(self):\n        self.c = 0\n    def __call__(self):\n        self.c += 1\n        return self.c\nf = Counter()\nfor _ in range(int(input())):\n    print(f())',E'Callable class: state attribute లో.'),
(210,176,E'Multiplier factory',E'3 5',E'15',E'def mul(n):\n    return lambda x: x * n\nn, x = map(int, input().split())\nprint(mul(n)(x))',E'mul(n) ఒక function return చేస్తుంది, అది n ని గుర్తుంచుకుంటుంది.',E'from functools import partial\nfrom operator import mul\nn, x = map(int, input().split())\nprint(partial(mul, n)(x))',E'functools.partial మొదటి argument fix చేస్తుంది.'),
(210,177,E'Logging decorator',E'2 3',E'calling add\n5',E'def log(fn):\n    def w(*a):\n        print(''calling'', fn.__name__)\n        return fn(*a)\n    return w\n@log\ndef add(a, b):\n    return a + b\nx, y = map(int, input().split())\nprint(add(x, y))',E'@log అంటే add = log(add); wrapper ముందు print చేసి original call చేస్తుంది.',E'class Log:\n    def __init__(self, fn):\n        self.fn = fn\n    def __call__(self, *a):\n        print(''calling'', self.fn.__name__)\n        return self.fn(*a)\n@Log\ndef add(a, b):\n    return a + b\nx, y = map(int, input().split())\nprint(add(x, y))',E'Class-based decorator: __call__ wrapper.'),
(210,178,E'Memoized Fibonacci',E'30',E'832040',E'def memo(fn):\n    c = {}\n    def w(n):\n        if n not in c:\n            c[n] = fn(n)\n        return c[n]\n    return w\n@memo\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\nprint(fib(int(input())))',E'Cache dict తో repeated calls తప్పించాం: exponential time → linear.',E'from functools import lru_cache\n@lru_cache(None)\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)\nprint(fib(int(input())))',E'Built-in lru_cache: మన memo అవసరం లేదు.'),
(210,179,E'Repeat decorator with argument',E'3',E'Hi\nHi\nHi',E'n = int(input())\ndef repeat(k):\n    def deco(fn):\n        def w():\n            for _ in range(k):\n                fn()\n        return w\n    return deco\n@repeat(n)\ndef hi():\n    print(''Hi'')\nhi()',E'Arguments ఉన్న decorator = 3 levels: repeat(k) → deco(fn) → w().',E'class Repeat:\n    def __init__(self, k):\n        self.k = k\n    def __call__(self, fn):\n        def w():\n            for _ in range(self.k):\n                fn()\n        return w\nn = int(input())\n@Repeat(n)\ndef hi():\n    print(''Hi'')\nhi()',E'Argument __init__ లో, function __call__ లో.'),
(210,180,E'Compose functions',E'3',E'8',E'def compose(*fs):\n    def run(x):\n        for f in reversed(fs):\n            x = f(x)\n        return x\n    return run\nadd1 = lambda x: x + 1\ndbl = lambda x: x * 2\nprint(compose(dbl, add1)(int(input())))',E'compose(g, f)(x) = g(f(x)); functions ని values లా వాడాం.',E'from functools import reduce\nadd1 = lambda x: x + 1\ndbl = lambda x: x * 2\nprint(reduce(lambda x, f: f(x), [add1, dbl], int(input())))',E'reduce తో functions ని వరుసగా apply.'),
(210,181,E'Tower of Hanoi moves',E'5',E'31',E'def h(n):\n    return 0 if n == 0 else 2 * h(n - 1) + 1\nprint(h(int(input())))',E'n-1 discs రెండుసార్లు + 1 move.',E'print(2 ** int(input()) - 1)',E'Recurrence solve చేస్తే 2ⁿ - 1.'),
(210,182,E'All permutations',E'abc',E'[''abc'', ''acb'', ''bac'', ''bca'', ''cab'', ''cba'']',E'def perm(s):\n    if len(s) <= 1:\n        return [s]\n    out = []\n    for i, c in enumerate(s):\n        for p in perm(s[:i] + s[i + 1:]):\n            out.append(c + p)\n    return out\nprint(perm(input()))',E'ఒక character ఎంచుకొని మిగిలిన వాటి permutations కి recursion.',E'from itertools import permutations\nprint([''''.join(p) for p in permutations(input())])',E'Library function: ఒక్క line.'),
(210,183,E'All subsets',E'1 2 3',E'[[], [1], [2], [1, 2], [3], [1, 3], [2, 3], [1, 2, 3]]',E'a = list(map(int, input().split()))\nres = [[]]\nfor x in a:\n    res += [r + [x] for r in res]\nprint(res)',E'ప్రతి element కి ఉన్న subsets రెట్టింపు.',E'a = list(map(int, input().split()))\nn = len(a)\nprint([[a[i] for i in range(n) if m >> i & 1] for m in range(1 << n)])',E'Bitmask: ప్రతి number లో set bits = ఎంచుకున్న elements.'),
(210,184,E'Minimum coins',E'1 2 5\n11',E'3',E'c = list(map(int, input().split()))\nt = int(input())\nINF = float(''inf'')\ndp = [0] + [INF] * t\nfor a in range(1, t + 1):\n    for x in c:\n        if x <= a:\n            dp[a] = min(dp[a], dp[a - x] + 1)\nprint(dp[t] if dp[t] != INF else -1)',E'dp[a] = a కి కనిష్ట coins. Bottom-up.',E'from functools import lru_cache\nc = list(map(int, input().split()))\nt = int(input())\nINF = float(''inf'')\n@lru_cache(None)\ndef f(a):\n    if a == 0:\n        return 0\n    return min((f(a - x) + 1 for x in c if x <= a), default=INF)\nprint(f(t) if f(t) != INF else -1)',E'అదే idea top-down recursion + memo.'),
(211,185,E'Min stack',E'7\npush 3\npush 1\npush 2\nmin\npop\npop\nmin',E'1\n3',E'class MinStack:\n    def __init__(self):\n        self.s = []\n        self.m = []\n    def push(self, x):\n        self.s.append(x)\n        self.m.append(min(x, self.m[-1]) if self.m else x)\n    def pop(self):\n        self.m.pop()\n        return self.s.pop()\n    def min(self):\n        return self.m[-1]\nst = MinStack()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''push'':\n        st.push(int(op[1]))\n    elif op[0] == ''pop'':\n        st.pop()\n    else:\n        print(st.min())',E'రెండో stack ప్రతి స్థాయిలో min ని ఉంచుతుంది: min() O(1).',E'class MinStack:\n    def __init__(self):\n        self.s = []\n    def push(self, x):\n        self.s.append((x, min(x, self.s[-1][1]) if self.s else x))\n    def pop(self):\n        return self.s.pop()[0]\n    def min(self):\n        return self.s[-1][1]\nst = MinStack()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''push'':\n        st.push(int(op[1]))\n    elif op[0] == ''pop'':\n        st.pop()\n    else:\n        print(st.min())',E'ఒకే stack లో (value, ఇప్పటి వరకు min) tuples.'),
(211,186,E'Queue using two stacks',E'6\nenq 1\nenq 2\ndeq\nenq 3\ndeq\ndeq',E'1\n2\n3',E'class Q:\n    def __init__(self):\n        self.a = []\n        self.b = []\n    def enq(self, x):\n        self.a.append(x)\n    def deq(self):\n        if not self.b:\n            while self.a:\n                self.b.append(self.a.pop())\n        return self.b.pop()\nq = Q()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''enq'':\n        q.enq(int(op[1]))\n    else:\n        print(q.deq())',E'b ఖాళీ అయినప్పుడే a ని తిరగేసి మార్చడం: amortized O(1).',E'from collections import deque\nclass Q:\n    def __init__(self):\n        self.d = deque()\n    def enq(self, x):\n        self.d.append(x)\n    def deq(self):\n        return self.d.popleft()\nq = Q()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''enq'':\n        q.enq(int(op[1]))\n    else:\n        print(q.deq())',E'deque తో నేరుగా O(1) both ends (two-stack idea కి ప్రత్యామ్నాయం).'),
(211,187,E'Vector operator overloading',E'1 2\n3 4',E'(4, 6) 5.0',E'class Vec:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n    def __add__(self, o):\n        return Vec(self.x + o.x, self.y + o.y)\n    def __abs__(self):\n        return (self.x ** 2 + self.y ** 2) ** .5\n    def __str__(self):\n        return f''({self.x}, {self.y})''\na = Vec(*map(int, input().split()))\nb = Vec(*map(int, input().split()))\nprint(a + b, abs(b))',E'+ కి __add__, abs() కి __abs__, print కి __str__.',E'from dataclasses import dataclass\n@dataclass\nclass Vec:\n    x: int\n    y: int\n    def __add__(self, o):\n        return Vec(self.x + o.x, self.y + o.y)\n    def __abs__(self):\n        return (self.x ** 2 + self.y ** 2) ** .5\n    def __str__(self):\n        return f''({self.x}, {self.y})''\na = Vec(*map(int, input().split()))\nb = Vec(*map(int, input().split()))\nprint(a + b, abs(b))',E'@dataclass __init__ ని auto తయారు చేస్తుంది.'),
(211,188,E'Compound interest (inheritance vs composition)',E'1000 5\n2',E'1102.5',E'class Account:\n    def __init__(self, b):\n        self.b = b\nclass Savings(Account):\n    def __init__(self, b, r):\n        super().__init__(b)\n        self.r = r\n    def grow(self, y):\n        for _ in range(y):\n            self.b *= 1 + self.r / 100\n        return round(self.b, 2)\nb, r = map(int, input().split())\ny = int(input())\nprint(Savings(b, r).grow(y))',E'Savings is-an Account (inheritance); ప్రతి సంవత్సరం interest.',E'class Account:\n    def __init__(self, b):\n        self.b = b\nclass Savings:\n    def __init__(self, acc, r):\n        self.acc = acc\n        self.r = r\n    def grow(self, y):\n        return round(self.acc.b * (1 + self.r / 100) ** y, 2)\nb, r = map(int, input().split())\ny = int(input())\nprint(Savings(Account(b), r).grow(y))',E'Savings has-an Account (composition); formula P(1+r)^y.'),
(211,189,E'Shapes polymorphism',E'2\ncircle 1\nrect 2 3',E'9.14',E'from abc import ABC, abstractmethod\nclass Shape(ABC):\n    @abstractmethod\n    def area(self):\n        pass\nclass Circle(Shape):\n    def __init__(self, r):\n        self.r = r\n    def area(self):\n        return 3.14159 * self.r ** 2\nclass Rect(Shape):\n    def __init__(self, a, b):\n        self.a = a\n        self.b = b\n    def area(self):\n        return self.a * self.b\nmk = {''circle'': Circle, ''rect'': Rect}\ntotal = 0\nfor _ in range(int(input())):\n    t, *v = input().split()\n    total += mk[t](*map(float, v)).area()\nprint(round(total, 2))',E'Abstract base class: ప్రతి shape area() implement చేయాలి.',E'f = {''circle'': lambda r: 3.14159 * r * r, ''rect'': lambda a, b: a * b}\ntotal = 0\nfor _ in range(int(input())):\n    t, *v = input().split()\n    total += f[t](*map(float, v))\nprint(round(total, 2))',E'Class లు లేకుండా dict of functions dispatch.'),
(211,190,E'Countdown iterator',E'5',E'5 4 3 2 1',E'class Down:\n    def __init__(self, n):\n        self.n = n\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.n == 0:\n            raise StopIteration\n        v = self.n\n        self.n -= 1\n        return v\nprint(*Down(int(input())))',E'Iterator protocol: __iter__ మరియు __next__, చివరికి StopIteration.',E'def down(n):\n    while n:\n        yield n\n        n -= 1\nprint(*down(int(input())))',E'Generator function అదే పని ఎక్కువ సులభంగా.'),
(211,191,E'2x2 matrix multiply (__mul__)',E'1 2 3 4\n5 6 7 8',E'[[19, 22], [43, 50]]',E'class M:\n    def __init__(self, v):\n        self.m = [v[:2], v[2:]]\n    def __mul__(self, o):\n        r = [[0, 0], [0, 0]]\n        for i in range(2):\n            for j in range(2):\n                for k in range(2):\n                    r[i][j] += self.m[i][k] * o.m[k][j]\n        x = M([0] * 4)\n        x.m = r\n        return x\na = M(list(map(int, input().split())))\nb = M(list(map(int, input().split())))\nprint((a * b).m)',E'మూడు nested loops తో row×column.',E'class M:\n    def __init__(self, v):\n        self.m = [v[:2], v[2:]]\n    def __mul__(self, o):\n        x = M([0] * 4)\n        x.m = [[sum(a * b for a, b in zip(row, col)) for col in zip(*o.m)] for row in self.m]\n        return x\na = M(list(map(int, input().split())))\nb = M(list(map(int, input().split())))\nprint((a * b).m)',E'zip(*o.m) columns ఇస్తుంది; comprehension తో.'),
(211,192,E'Inventory system',E'5\nadd apple 3\nadd pear 2\nremove apple 1\nadd apple 2\nreport',E'{''apple'': 4, ''pear'': 2}',E'class Inv:\n    def __init__(self):\n        self.d = {}\n    def add(self, n, q):\n        self.d[n] = self.d.get(n, 0) + q\n    def remove(self, n, q):\n        self.d[n] = max(0, self.d.get(n, 0) - q)\ninv = Inv()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''add'':\n        inv.add(op[1], int(op[2]))\n    elif op[0] == ''remove'':\n        inv.remove(op[1], int(op[2]))\n    else:\n        print(dict(inv.d))',E'Dict state ఉన్న class; stock 0 కంటే తక్కువ కాదు.',E'from collections import Counter\nclass Inv:\n    def __init__(self):\n        self.d = Counter()\n    def add(self, n, q):\n        self.d[n] += q\n    def remove(self, n, q):\n        self.d[n] = max(0, self.d[n] - q)\ninv = Inv()\nfor _ in range(int(input())):\n    op = input().split()\n    if op[0] == ''add'':\n        inv.add(op[1], int(op[2]))\n    elif op[0] == ''remove'':\n        inv.remove(op[1], int(op[2]))\n    else:\n        print(dict(inv.d))',E'Counter missing key కి 0 default ఇస్తుంది.'),
(211,193,E'Reverse a linked list',E'1 2 3 4',E'4 3 2 1',E'class Node:\n    def __init__(self, v):\n        self.v = v\n        self.next = None\nvals = list(map(int, input().split()))\nhead = None\nfor v in reversed(vals):\n    n = Node(v)\n    n.next = head\n    head = n\nprev = None\nwhile head:\n    nxt = head.next\n    head.next = prev\n    prev = head\n    head = nxt\nout = []\nwhile prev:\n    out.append(prev.v)\n    prev = prev.next\nprint(*out)',E'Iterative: ప్రతి node pointer ని వెనక్కి తిప్పాం. O(1) space.',E'class Node:\n    def __init__(self, v):\n        self.v = v\n        self.next = None\ndef rev(h, p=None):\n    if not h:\n        return p\n    n = h.next\n    h.next = p\n    return rev(n, h)\nvals = list(map(int, input().split()))\nhead = None\nfor v in reversed(vals):\n    n = Node(v)\n    n.next = head\n    head = n\nh = rev(head)\nout = []\nwhile h:\n    out.append(h.v)\n    h = h.next\nprint(*out)',E'Recursive: అదే pointer మార్పు, call stack O(n).'),
(211,194,E'Polynomial addition',E'1 2 3\n4 5',E'[5, 7, 3]',E'from itertools import zip_longest\nclass Poly:\n    def __init__(self, c):\n        self.c = c\n    def __add__(self, o):\n        return Poly([a + b for a, b in zip_longest(self.c, o.c, fillvalue=0)])\na = Poly(list(map(int, input().split())))\nb = Poly(list(map(int, input().split())))\nprint((a + b).c)',E'zip_longest తో పొడవు తేడా handle.',E'class Poly:\n    def __init__(self, c):\n        self.c = c\n    def __add__(self, o):\n        r = [0] * max(len(self.c), len(o.c))\n        for i, v in enumerate(self.c):\n            r[i] += v\n        for i, v in enumerate(o.c):\n            r[i] += v\n        return Poly(r)\na = Poly(list(map(int, input().split())))\nb = Poly(list(map(int, input().split())))\nprint((a + b).c)',E'పొడవైనదాని size లో array చేసి రెండూ add.'),
(212,195,E'Count valid and invalid tokens',E'10 x 20 3.5 5',E'35 2',E'total = bad = 0\nfor t in input().split():\n    try:\n        total += int(t)\n    except ValueError:\n        bad += 1\nprint(total, bad)',E'int(''3.5'') కూడా ValueError.',E'total = bad = 0\nfor t in input().split():\n    if t.lstrip(''-'').isdigit():\n        total += int(t)\n    else:\n        bad += 1\nprint(total, bad)',E'LBYL: ముందు check చేసి convert (exception వాడలేదు).'),
(212,196,E'Custom exception hierarchy',E'100\n150',E'InsufficientFunds: need 50 more',E'class BankError(Exception):\n    pass\nclass InsufficientFunds(BankError):\n    def __init__(self, need):\n        super().__init__(f''InsufficientFunds: need {need} more'')\nbal = int(input())\namt = int(input())\ntry:\n    if amt > bal:\n        raise InsufficientFunds(amt - bal)\n    print(bal - amt)\nexcept BankError as e:\n    print(e)',E'Subclass ని parent BankError తోనే catch చేయవచ్చు.',E'class InsufficientFunds(Exception):\n    def __init__(self, need):\n        self.need = need\nbal = int(input())\namt = int(input())\ntry:\n    if amt > bal:\n        raise InsufficientFunds(amt - bal)\n    print(bal - amt)\nexcept InsufficientFunds as e:\n    print(f''InsufficientFunds: need {e.need} more'')',E'Exception లో data attribute గా; message బయట format.'),
(212,197,E'Context manager suppressing errors',E'boom',E'enter\nexit ValueError\nafter',E'class Ctx:\n    def __enter__(self):\n        print(''enter'')\n        return self\n    def __exit__(self, t, v, tb):\n        print(''exit'', t.__name__ if t else ''None'')\n        return True\nmsg = input()\nwith Ctx():\n    raise ValueError(msg)\nprint(''after'')',E'__exit__ True return చేస్తే exception suppress అవుతుంది.',E'from contextlib import contextmanager\n@contextmanager\ndef ctx():\n    print(''enter'')\n    try:\n        yield\n    except Exception as e:\n        print(''exit'', type(e).__name__)\nmsg = input()\nwith ctx():\n    raise ValueError(msg)\nprint(''after'')',E'@contextmanager generator: yield చుట్టూ try/except.'),
(212,198,E'Retry until success',E'2 5',E'Success after 3 attempts',E'k, n = map(int, input().split())\ncalls = 0\ndef flaky():\n    global calls\n    calls += 1\n    if calls <= k:\n        raise RuntimeError(''fail'')\nfor attempt in range(1, n + 1):\n    try:\n        flaky()\n        print(f''Success after {attempt} attempts'')\n        break\n    except RuntimeError:\n        pass\nelse:\n    print(f''Failed after {n} attempts'')',E'Loop + try/except; for-else అన్నీ విఫలమైతే.',E'k, n = map(int, input().split())\ncalls = 0\ndef flaky():\n    global calls\n    calls += 1\n    if calls <= k:\n        raise RuntimeError(''fail'')\ndef retry(a):\n    try:\n        flaky()\n        return f''Success after {a} attempts''\n    except RuntimeError:\n        return retry(a + 1) if a < n else f''Failed after {n} attempts''\nprint(retry(1))',E'Recursion తో retry; base: max attempts.');
